    bandwidth = max(np.std(observed) * 1.06 * len(observed) ** (-1 / 5), 0.03)
    density = np.mean(np.exp(-0.5 * ((x - observed) / bandwidth) ** 2) / (bandwidth * math.sqrt(2 * math.pi)))
    return math.log(max(density, 1e-12))

